const app={compare:[],filter:{query:'',discipline:'All disciplines',level:'All levels'},applyStep:1,application:{},modal:null,theme:localStorage.getItem('jsid-theme')||'auto',lastPath:null};
const $=s=>document.querySelector(s);
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(href,label,cls='text-link')=>`<a class="${cls}" href="#${href}">${label}</a>`;
const note=()=>'';
const list=items=>`<ul class="content-list">${items.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`;
const cards=items=>`<div class="route-card-grid">${items.map(([title,body])=>`<div class="route-card"><h3>${escapeHtml(title)}</h3><p>${escapeHtml(body)}</p></div>`).join('')}</div>`;
