const crumb=(items)=>`<nav class="breadcrumb" aria-label="Breadcrumb"><a href="#/">Home</a>${items.map(([name,url])=>`<span aria-hidden="true">/</span>${url?`<a href="#${url}">${escapeHtml(name)}</a>`:`<span aria-current="page">${escapeHtml(name)}</span>`}`).join('')}</nav>`;
function hero(title,eyebrow,lead,opts={}){return `<section class="page-hero ${opts.accent?'page-hero-accent':''}"><div class="container">${crumb(opts.crumb||[[title,null]])}<span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="lead">${lead}</p>${opts.actions?`<div class="page-hero-actions">${opts.actions}</div>`:''}</div></section>`}
function block(id,title,body){return `<section class="content-block" id="${id}"><h2>${title}</h2>${body}</section>`}
function indexLayout(items,body){return `<section class="section"><div class="container content-layout"><nav class="side-index" aria-label="On this page">${items.map(([id,name])=>`<a href="#${id}" data-anchor="${id}">${name}</a>`).join('')}</nav><div class="content-stack">${body}</div></div></section>`}
function programCard(p){return `<article class="card"><div class="card-art ${p.art}" aria-hidden="true"></div><div class="card-body"><div class="card-meta">${p.discipline} · ${p.level}</div><h3>${escapeHtml(p.name)}</h3><p>Explore curriculum, eligibility, work, faculty and outcomes in one place.</p><div class="program-card-actions">${link(`/program/${p.slug}`,'View program <span aria-hidden="true">↗</span>')}<button class="compare-toggle" data-compare="${p.slug}" aria-pressed="${app.compare.includes(p.slug)}">${app.compare.includes(p.slug)?'Added':'Compare +'}</button></div></div></article>`}
function editorialCard(type,title,desc,url){return `<article class="editorial-item"><span class="tag">${escapeHtml(type)}</span><h3>${escapeHtml(title)}</h3><p>${escapeHtml(desc)}</p>${url?`<a class="text-link" href="${url}" target="_blank" rel="noopener noreferrer">${url.endsWith('/blogs/')?'Explore the current JSID blog':'Read on the current JSID site'} ↗</a>`:''}</article>`}
function faq(items){return `<div class="accordion">${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`}
function renderHome(){return `<section class="hero hero--image"><img class="hero-photo" src="./assets/hero-editorial.png" alt="Illustrative image of design students collaborating on an architectural model" fetchpriority="high"><div class="hero-overlay"><span class="eyebrow">Welcome to JS Institute of Design</span><h1>Find your place in design.</h1><p>Explore a program, support a student, reconnect as an alumnus, or meet the people who teach here.</p><div class="hero-button-grid" aria-label="Choose your path">
  ${[['I want to study design','/programs'],['I’m a parent or guardian','/parents'],['I’m an alumnus','/alumni'],['I teach or want to collaborate','/faculty']].map(x=>`<a class="hero-role-button" href="#${x[1]}" data-audience="${x[0]}">${x[0]} <span aria-hidden="true">↗</span></a>`).join('')}</div></div></section>
  <div class="hero-shortcuts"><div class="container hero-shortcuts-inner"><span class="mini-label">Popular links</span><div class="quicklinks"><a href="#/admissions">Admissions dates</a><a href="#/admissions#scholarships">Scholarships</a><a href="#/campus-life">Campus Life</a><a href="#/contact?topic=cost">Ask about exact costs</a></div></div></div>
  <section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">Academics</span><h2>Explore the programs</h2></div>${link('/programs','See all programs <span aria-hidden="true">↗</span>')}</div><div class="card-grid">${[programs[0],programs[4],programs[6]].map(programCard).join('')}</div></div></section>
  <section class="section" style="background:var(--paper)"><div class="container split-section"><div><span class="eyebrow">Learning in action</span><h2>See what students make.</h2><p class="lead">A space for student projects, creative process and the programs behind them.</p>${link('/programs','Find the program behind the work <span aria-hidden="true">↗</span>')}</div><div class="graphic-panel" role="img" aria-label="Abstract graphic representing student work"><span>MAKE</span></div></div></section>
  <section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">Evidence and people</span><h2>Look beyond the brochure.</h2></div></div><div class="route-card-grid"><div class="route-card"><span class="mini-label">Student Outcomes</span><h3>Placements, entrepreneurship and study abroad</h3><p>Explore possible directions after a design education.</p>${link('/student-outcomes','Explore outcomes ↗')}</div><div class="route-card"><span class="mini-label">Faculty</span><h3>Meet the people behind the programs</h3><p>Faculty profiles connect academic areas to the programs they teach.</p>${link('/faculty','Explore faculty ↗')}</div><div class="route-card"><span class="mini-label">Campus Life</span><h3>Student life and resident life</h3><p>Find the campus, accommodation and everyday facilities.</p>${link('/campus-life','Explore campus life ↗')}</div><div class="route-card"><span class="mini-label">News & Media</span><h3>What’s happening at JSID</h3><p>Explore news, events and creative ideas from JSID.</p>${link('/news-media','Read updates ↗')}</div></div></div></section>
  <section class="banner"><div class="container split-section"><div><span class="eyebrow" style="color:#eafa45">Next step</span><h2>Ready to look closer?</h2><p>Compare programs, check the admissions process, or send a specific question.</p></div><div class="hero-actions">${link('/programs','Compare programs','button button-yellow')}${link('/admissions','Review admissions','button button-outline')}${link('/contact','Ask a question','button button-outline')}</div></div></section>`}
function renderPrograms(){return `${hero('Find your program','Academics','Browse by discipline and level, then compare the details that matter.',{crumb:[['Academics',null]],actions:link('/admissions','How to apply ↗','button button-dark')})}<section class="section"><div class="container">${note('')}<div class="filters"><input id="program-search" type="search" placeholder="Search a program or discipline" aria-label="Search programs" value="${escapeHtml(app.filter.query)}"><select id="discipline-filter" aria-label="Filter by discipline"><option>All disciplines</option><option>Interior Design</option><option>Digital Design</option></select><select id="level-filter" aria-label="Filter by level"><option>All levels</option><option>Undergraduate</option><option>Postgraduate</option><option>Integrated</option></select></div><div id="program-count" class="count-label"></div><div id="program-grid" class="card-grid"></div><div class="section-tight"><span class="eyebrow">High School Students</span><h2>Explore design earlier.</h2><div class="route-card-grid"><div class="route-card"><h3>Summer offering</h3><p>Explore a short design experience and ask JSID for the current schedule.</p>${link('/high-school/summer','Explore Summer ↗')}</div><div class="route-card"><h3>Winter offering</h3><p>Explore a short design experience and ask JSID for the current schedule.</p>${link('/high-school/winter','Explore Winter ↗')}</div></div></div></div></section>`}
function renderCompare(){const selected=app.compare.map(s=>programs.find(p=>p.slug===s)).filter(Boolean);if(selected.length<2)return `${hero('Compare programs','Academics','Choose two programs to view them side by side.',{crumb:[['Academics','/programs'],['Compare',null]]})}<section class="section"><div class="container">${link('/programs','Choose programs ↗')}</div></section>`;return `${hero('Compare programs','Decision support','See the learning focus and key details side by side.',{crumb:[['Academics','/programs'],['Compare',null]],actions:link('/programs','Change selection','button button-outline')})}<section class="section"><div class="container"><div class="compare-table">${[['Program',...selected.map(p=>p.name)],['Discipline',...selected.map(p=>p.discipline)],['Level',...selected.map(p=>p.level)],['Study route',...selected.map(p=>programDetails[p.slug].qualification)],['Duration',...selected.map(p=>programDetails[p.slug].duration)],['Entry route',...selected.map(p=>p.level==='Postgraduate'?'Undergraduate degree':'Grade 12 or equivalent')],['Focus',...selected.map(p=>programDetails[p.slug].overview)],['Costs',...selected.map(()=> 'Ask Admissions for the current fee schedule')],['Next step',...selected.map(p=>`<a class="text-link" href="#/program/${p.slug}">View program ↗</a>`)]].map(row=>row.map((cell,i)=>`<div class="${i===0?'compare-label':''}">${cell}</div>`).join('')).join('')}</div></div></section>`}
function renderProgram(p){const d=programDetails[p.slug],sections=[['overview','Program overview'],['learn','What you will learn'],['curriculum','Curriculum'],['faculty','Faculty'],['work','Student work'],['outcomes','Career outcomes'],['voices','Student and alumni voices'],['admissions','Admissions and eligibility']];const entry=p.level==='Postgraduate'?'An undergraduate degree is the general entry requirement for postgraduate study.':'Grade 12 or an equivalent qualification is the general entry requirement for undergraduate study.';const body=[
  block('overview','Program overview',`<p>${escapeHtml(d.overview)}</p><div class="metric-row"><div class="metric-card"><span class="mini-label">Learning style</span><strong>Studio projects</strong><p>Research, making and presentation.</p></div><div class="metric-card"><span class="mini-label">Explore further</span><strong>People and practice</strong><p>Meet faculty and see related work.</p></div></div>`),
  block('learn','What you will learn',`<p>Build a foundation you can use across briefs, studios and future practice.</p>${list(d.learn)}`),
  block('curriculum','Curriculum',`<p>Follow the development of the course from foundations to applied work.</p><div class="timeline">${d.stages.map(([name,body],i)=>`<div class="timeline-item"><span class="mini-label">${String(i+1).padStart(2,'0')}</span><h3>${escapeHtml(name)}</h3><p>${escapeHtml(body)}</p></div>`).join('')}</div>`),
  block('faculty','Faculty',`<p>Learn with teachers and practitioners working across ${escapeHtml(d.faculty.toLowerCase())}.</p>${link('/faculty','Meet faculty and mentors ↗')}`),
  block('work','Student work',`<p>See the kind of brief you could explore in this program.</p><div class="card-art ${p.art}" style="height:260px" role="img" aria-label="Abstract illustration of a design project"></div><h3>Project idea</h3><p>${escapeHtml(d.work)}</p>`),
  block('outcomes','Career outcomes',`<p>Graduates can explore a range of roles depending on their portfolio, interests and experience.</p>${list(d.roles)}${link('/student-outcomes','Explore Student Outcomes ↗')}`),
  block('voices','Student and alumni voices',`<p>Look at student work, events and graduate paths to understand how people use what they learn.</p>${cards([['Student perspectives','Browse projects and events from the design community.'],['Alumni paths','See how graduates carry their practice into different roles and industries.']])}${link('/alumni','Explore Alumni ↗')}`),
  block('admissions','Admissions and eligibility',`<p>${entry} Check the current course-specific criteria and intake details with Admissions before applying.</p><div class="form-actions">${link('/admissions','Review admissions','button button-outline')}${link('/apply?program='+p.slug,'Start application','button button-dark')}</div>`)
].join('');return `${hero(escapeHtml(p.name),`${p.discipline} · ${p.level}`,escapeHtml(d.overview),{accent:true,crumb:[['Academics','/programs'],[p.discipline,'/programs'],[p.name,null]],actions:`<button class="button button-dark" data-brochure="${p.slug}">Explore brochure ↗</button>${link('/apply?program='+p.slug,'Apply','button button-outline')}`})}<div class="container"><div class="fact-grid">${[['Study route',d.qualification],['Duration',d.duration],['Entry route',p.level==='Postgraduate'?'Undergraduate degree':'Grade 12 or equivalent'],['Current intake','2027 applications open']].map(x=>`<div class="fact"><span>${x[0]}</span><strong>${escapeHtml(x[1])}</strong></div>`).join('')}</div></div>${indexLayout(sections,body)}<section class="section-tight"><div class="container banner"><h2>Need an exact cost answer?</h2><p>Ask Admissions for the fee schedule for your chosen program and intake.</p>${link('/contact?topic=cost&program='+p.slug,'Ask about costs ↗','button button-yellow')}</div></section>`}
function renderAdmissions(){const sections=[['how','How to apply'],['intake','Current intake'],['eligibility','Eligibility'],['selection','Selection process'],['scholarships','Scholarships'],['refunds','Fees and refunds'],['faqs','Frequently asked questions']];return `${hero('Admissions','Your path to JSID','Explore the process, check your entry route and ask Admissions for the details that apply to your program.',{actions:`${link('/apply','Explore application steps ↗','button button-dark')}<button class="button button-outline" data-brochure="">Explore brochures</button>`,crumb:[['Admissions',null]]})}${indexLayout(sections,
  block('how','How to apply',`<div class="timeline">${[['01','Choose a program','Explore the curriculum, learning style and possible career directions.'],['02','Check entry requirements','Undergraduate and postgraduate routes have different minimum qualifications.'],['03','Prepare your work','Gather academic records and a portfolio of creative work where requested.'],['04','Contact Admissions','Confirm the current dates, assessment steps and application link.']].map(x=>`<div class="timeline-item"><span class="mini-label">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div>`)+
  block('intake','Current intake',`<p>JSID’s current website announces that applications are open for the 2027 intake. Ask Admissions for the exact program deadline and any assessment dates.</p>${link('/contact?topic=admissions','Ask about dates ↗')}`)+
  block('eligibility','Eligibility',`<p>For undergraduate study, JSID lists Grade 12 or an equivalent qualification as the minimum entry route. For postgraduate study, it lists an undergraduate degree from any field.</p>${link('/programs','Find your program ↗')}`)+
  block('selection','Selection process',`<p>Admission and scholarship decisions can consider academic work, creative assessment, an interview and a portfolio. Ask Admissions which steps apply to your program.</p>${cards([['Show your thinking','Select a few pieces that explain your ideas and process.'],['Talk through your work','Prepare to discuss the choices behind a project, not just the finished result.']])}`)+
  block('scholarships','Scholarships',`<p>JSID’s current admissions page describes merit-based scholarships and lists academic merit, a creative intelligence test, interview and portfolio among the criteria. Availability and terms can change by intake.</p>${link('/contact?topic=cost','Ask about current scholarships ↗')}`)+
  block('refunds','Fees and refunds',`<p>For a decision involving money, request the current written fee schedule and refund terms for your specific program and intake from Admissions.</p>${link('/contact?topic=cost','Ask about fees and refunds ↗')}`)+
  block('faqs','Frequently asked questions',faq([['Where can I find the next admission dates?','Ask Admissions for the dates attached to your chosen program and intake.'],['How do I find out the exact cost?','Request the current written fee schedule for your program.'],['Is exploring a brochure the same as applying?','No. Brochure information and an application are separate steps.']])))}<section class="banner"><div class="container"><h2>Take the next step.</h2><div class="hero-actions">${link('/apply','Explore application steps','button button-yellow')}${link('/contact?topic=admissions','Ask Admissions','button button-outline')}</div></div></section>`}
function renderApply(){let step=app.applyStep;return `${hero('Apply to JSID','Application journey','Review the application steps and the information you will need to provide.',{crumb:[['Admissions','/admissions'],['Apply',null]]})}<section class="section"><div class="container" style="max-width:850px">${note('The agreed live baseline is a Headstart iframe. This form is not connected to admissions and does not send personal information.')}<div class="stepper"><span class="${step===1?'active':''}">1 · Choose program</span><span class="${step===2?'active':''}">2 · Applicant details</span><span class="${step===3?'active':''}">3 · Review</span><span class="${step===4?'active':''}">4 · Confirmation</span></div><div id="apply-step">${applyStepHtml()}</div></div></section>`}
function applyStepHtml(){const step=app.applyStep;if(step===1)return `<h2>Choose a program</h2><p>Program context should carry into the real application.</p><form id="apply-program-form"><div class="form-field"><label for="apply-program">Program</label><select id="apply-program" required><option value="">Select a program</option>${programs.map(p=>`<option value="${p.slug}" ${app.application.program===p.slug?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</select></div><div class="form-actions"><button class="button button-dark" type="submit">Continue ↗</button></div></form>`;if(step===2)return `<h2>Applicant details</h2><p>Use these fields to review the application steps. No details are sent.</p><form id="apply-details-form"><div class="form-grid"><div class="form-field"><label for="applicant-name">Full name</label><input id="applicant-name" name="name" required autocomplete="name" value="${escapeHtml(app.application.name||'')}"></div><div class="form-field"><label for="applicant-email">Email address</label><input id="applicant-email" name="email" type="email" required autocomplete="email" value="${escapeHtml(app.application.email||'')}"></div></div><p class="form-note">These details are not sent or saved.</p><div class="form-actions"><button type="button" class="button button-outline" data-apply-back>Back</button><button class="button button-dark" type="submit">Review ↗</button></div></form>`;if(step===3){const p=programs.find(x=>x.slug===app.application.program);return `<h2>Review your next step</h2><div class="metric-card"><span class="mini-label">Program</span><strong>${escapeHtml(p?.name||'Not selected')}</strong><p>${escapeHtml(app.application.name||'')} · ${escapeHtml(app.application.email||'')}</p></div><p>The final step will continue to the application system when it is connected.</p><div class="form-actions"><button type="button" class="button button-outline" data-apply-back>Back</button><button type="button" class="button button-dark" data-apply-finish>Finish review ↗</button></div>`}return `<span class="eyebrow">Review complete</span><h2>Application steps reviewed.</h2><p>No application was submitted.</p>${link('/admissions','Return to Admissions ↗','button button-outline')}`}
function renderParents(){const items=[['learning','Learning at JSID'],['achievements','Student achievements'],['campus','Campus and daily life'],['dates','Admissions and key dates'],['finance','Costs and scholarships'],['questions','Frequently asked questions']];return `${hero('For Parents','A clearer view of the decision','Find the questions, people and practical details that help you support a student’s choice.',{crumb:[['Parents',null]],actions:link('/contact?topic=cost','Ask about costs ↗','button button-dark')})}${indexLayout(items,
  block('learning','Learning at JSID',`<p>JSID describes project-based learning, studio practice and exposure to industry. Start with the course your student is considering and look at what they will actually make.</p>${cards([['Explore programs','Compare learning focus, duration and entry route.'],['Meet the teachers','See faculty and mentor practice areas.']])}${link('/programs','View programs ↗')}`)+
  block('achievements','Student achievements',`<p>Student projects and dated news offer a closer look at learning in action. The outcomes page also explains possible career directions.</p>${link('/student-outcomes','See Student Outcomes ↗')}`)+
  block('campus','Campus and daily life',`<p>Ask about the campus assigned to your student’s intake, daily travel, accommodation and support before making plans. JSID’s current site mentions both its Delhi location and a new Noida chapter.</p>${link('/campus-life','Explore Campus Life ↗')}`)+
  block('dates','Admissions and key dates',`<p>Applications are advertised for the 2027 intake. Confirm the deadline for the chosen program directly with Admissions.</p>${link('/admissions','Review Admissions ↗')}`)+
  block('finance','Costs and scholarships',`<p>Ask for a written breakdown of tuition, any additional charges, scholarship terms and refund rules for the relevant intake.</p><div class="form-actions">${link('/admissions#scholarships','Explore scholarships','button button-outline')}${link('/contact?topic=cost','Ask about costs','button button-dark')}</div>`)+
  block('questions','Frequently asked questions',faq([['What qualification will my child receive?','Check the current award and awarding body with Admissions for the chosen course.'],['Where will students study?','Confirm the campus location for the relevant program and intake.'],['How can I speak to someone?','Use the contact details to reach Admissions directly.']])))} `}
function renderOutcomes(){return `${hero('Student Outcomes','Where design can take you','Explore possible directions through work, practice and further study.',{crumb:[['Student Outcomes',null]]})}<section class="section"><div class="container"><div class="metric-row"><div class="metric-card"><strong>Employment</strong><p>Design studios, agencies and product teams.</p></div><div class="metric-card"><strong>Independent practice</strong><p>Freelance work, collaborations and new ventures.</p></div><div class="metric-card"><strong>Further study</strong><p>Specialisation and international pathways.</p></div></div><div class="section-tight">${cards([['Build a portfolio','Studio briefs, internships and final projects help students show how they think and make.'],['Find your direction','Explore role families on each program page, from spatial design to motion and digital products.'],['Keep learning','Courses, workshops and practice can open new paths after graduation.']])}</div>${link('/programs','Explore programs ↗')}</div></section>`}
function renderAlumni(){return `${hero('Alumni','The work continues','See graduate paths, reconnect with JSID and share what you have been making.',{crumb:[['Alumni',null]]})}<section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">Community</span><h2>Where do designers go next?</h2></div></div><div class="editorial-list">${editorialCard('Career path','Studio and agency practice','Visual communication, spatial design and digital product work can lead into many kinds of teams.')}${editorialCard('Independent practice','Building a personal practice','Graduates may combine client work, collaborations and their own creative ventures.')}</div><div class="section-tight">${cards([['Share your story','Tell JSID about a project, award or new direction.'],['Reconnect','Ask about talks, critiques, mentoring or community events.']])}</div><div class="banner"><h2>Stay connected.</h2><p>Write to JSID if you would like to share an update or connect with the community.</p>${link('/contact?topic=alumni','Contact JSID ↗','button button-yellow')}</div></div></section>`}
function renderAbout(){return `${hero('About JSID','The institute','Design education shaped by studio work, mentors and industry practice.',{crumb:[['About JSID',null]]})}<section class="section"><div class="container split-section"><div><span class="eyebrow">Who we are</span><h2>Ideas are made here.</h2><p class="lead">JS Institute of Design grew from a home and interiors legacy associated with Jagdish Store. Its current site connects design education with practical projects and a collaboration with École Intuit Lab.</p>${link('/founding-team','Meet the founders ↗')}</div><div class="graphic-panel" role="img" aria-label="Abstract institutional artwork"><span>JSID</span></div></div></section><section class="section" style="background:var(--paper)"><div class="container"><div class="section-head"><div><span class="eyebrow">Our approach</span><h2>People, practice, place.</h2></div></div>${cards([['Studio learning','Develop ideas through research, making, critique and revision.'],['Experienced mentors','Learn from designers and educators working across different fields.'],['Creative community','See the work, events and conversations happening around the institute.']])}<div class="form-actions">${link('/faculty','Meet faculty ↗')}${link('/campus-life','Explore campus life ↗')}</div></div></section>`}
function renderFounders(){return `${hero('Founding Team','About JSID','Meet the people and legacy behind the institute.',{crumb:[['About JSID','/about'],['Founding Team',null]]})}<section class="section"><div class="container"><div class="card-grid">${[['Dr. Pramath Raj Sinha','Founder and chairman','An education leader associated with the founding of JSID and several higher education initiatives.'],['Late Jagdish Khandelwal','Founder, Jagdish Store','The home furnishings business he founded is part of the institute’s origin story.']].map(([name,role,body],i)=>`<div class="card"><div class="card-art ${i?'art-b':'art-a'}" aria-hidden="true"></div><div class="card-body"><span class="card-meta">${role}</span><h3>${name}</h3><p>${body}</p></div></div>`).join('')}</div></div></section>`}
function renderFaculty(){const people=[['Prof. Nidhi Gupta','Design research and brand practice','Design educator and practitioner working across research, brand and consumer experience.'],['Prof. Jatin Bhatt','Design practice and games','Design academic and practitioner with experience in design education and consultancy.'],['Mr. Ravi Dhingra','Photography','Photographer working across architecture, interiors, portraits and products.'],['Prof. Seema Srivastava','Art history','Teacher and cultural theorist working in art and design education.']];return `${hero('Faculty','About JSID','Meet some of the people shaping design learning at JSID.',{crumb:[['About JSID','/about'],['Faculty',null]],actions:link('/careers','Explore careers ↗','button button-dark')})}<section class="section"><div class="container"><div class="card-grid">${people.map(([name,area,body],i)=>`<article class="card"><div class="card-art ${['art-a','art-b','art-c','art-d'][i]}" aria-hidden="true"></div><div class="card-body"><span class="card-meta">${area}</span><h3>${name}</h3><p>${body}</p>${link('/programs','Explore programs ↗')}</div></article>`).join('')}</div><div class="section-tight"><h2>Learn from different practices</h2><p>Faculty and mentors bring perspectives from research, photography, art, communication and spatial design.</p>${link('/programs','Explore programs ↗')}</div></div></section>`}
function renderCampus(){const items=[['student-life','Student Life'],['spaces','Spaces for making'],['resident-life','Resident Life'],['food','Food and breaks'],['activities','Beyond the studio'],['around','Getting there']];return `${hero('Campus Life','Make this place yours','Explore the spaces, people and daily rhythm around design study.',{crumb:[['Campus Life',null]]})}${indexLayout(items,
  block('student-life','Student Life',`<p>Studio projects, workshops, exhibitions and shared briefs bring students together beyond a single classroom.</p>${link('/news-media','See recent events ↗')}`)+
  block('spaces','Spaces for making',`<p>Design learning needs room to draw, prototype, review and present. Explore the kinds of spaces that support different ways of working.</p>${cards([['Studios','A place for making, critique and group work.'],['Digital work','Tools and production spaces for visual and interactive practice.'],['Show and tell','Display work, share process and invite feedback.']])}`)+
  block('resident-life','Resident Life',`<p>Planning to move for your course? Speak with Admissions about accommodation options, availability and the campus assigned to your intake.</p>${link('/contact?topic=admissions','Ask about accommodation ↗')}`)+
  block('food','Food and breaks',`<p>Everyday routines matter. Ask about current food arrangements, breaks and facilities when you plan a visit.</p>${link('/contact','Contact JSID ↗')}`)+
  block('activities','Beyond the studio',`<p>Events and workshops give students a chance to meet new people and try unfamiliar ways of making. JSID’s news archive includes art workshops and game jams.</p>${link('/news-media','Explore News & Media ↗')}`)+
  block('around','Getting there',`<p>JSID’s current website lists a Delhi address near Moolchand and also announces a new Noida campus. Confirm the location for your course and intake before travelling.</p>${link('/contact','Plan a visit ↗')}`))}`}
function renderSchool(season){const isSummer=season==='Summer';return `${hero(`${season} design experience`,'Academics · High School Students',`A short introduction to design thinking, making and creative exploration.`,{crumb:[['Academics','/programs'],['High School Students','/programs'],[`${season} offering`,null]]})}<section class="section"><div class="container"><div class="metric-row"><div class="metric-card"><span class="mini-label">Who it is for</span><strong>School students</strong></div><div class="metric-card"><span class="mini-label">Format</span><strong>Short experience</strong></div><div class="metric-card"><span class="mini-label">Next step</span><strong>Ask JSID</strong></div></div><div class="section-tight">${cards([['Explore a brief',isSummer?'Start with observation, drawing and a real-world question.':'Explore an idea through a compact seasonal design challenge.'],['Make and test','Try sketches, models or digital experiments and learn from feedback.'],['Share your work','Present a small project and talk through your choices.']])}<h2>How to join</h2><p>Ask JSID about the current schedule, age group, location and registration process for this seasonal offering.</p>${link('/contact?topic=high-school','Ask about this offering ↗','button button-dark')}</div></div></section>`}
function renderEditorial(kind){const news=kind==='news';const title=news?'News & Media':'Blog';const records=news?[
  ['News · 17 Apr 2025','Game art student recognised in an EA challenge','JSID reported that Eshan Kaushik placed third in an international game development challenge.','https://js-instituteofdesign.com/news-events/'],
  ['Workshop · 8 Apr 2025','Exploring creativity in the age of AI','An art workshop with Dutch artist Dadara invited students to examine technology and human expression.','https://js-instituteofdesign.com/news-events/'],
  ['Campus · Feb 2025','Global Game Jam at JSID','Students and other participants made games together during a 48-hour event.','https://js-instituteofdesign.com/news-events/'],
  ['Community · 10 Mar 2025','North Eastern Day at JSID','A campus event celebrated North Eastern traditions through music and art.','https://js-instituteofdesign.com/news-events/']
]:[
  ['Visual communication','What a visual communication degree covers','A closer look at the disciplines, skills and practice behind visual communication.','https://js-instituteofdesign.com/blogs/'],
  ['Game design','What game design study can lead to','Ideas on portfolio building and careers in interactive worlds.','https://js-instituteofdesign.com/blogs/'],
  ['Design education','Why making matters in design school','Thoughts on hands-on learning and creative process.','https://js-instituteofdesign.com/blogs/'],
  ['Digital practice','The role of motion in digital experiences','How movement can shape communication and interaction.','https://js-instituteofdesign.com/blogs/']
];return `${hero(title,news?'Updates and coverage':'Ideas and perspectives',news?'Stories and events from the JSID community.':'Read ideas from across design practice and education.',{crumb:[[title,null]]})}<section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">${news?'From the archive':'Articles'}</span><h2>${news?'Stories from JSID':'Explore the blog'}</h2></div></div><div class="editorial-list">${records.map(x=>editorialCard(...x)).join('')}</div>${news?`<div class="section-tight">${link('/events','See events ↗')}</div>`:''}</div></section>`}
function renderEvents(){return `${hero('Events','Meet the community','Find workshops, talks and moments of making from the JSID community.',{crumb:[['Events',null]]})}<section class="section"><div class="container">${cards([['Art and ideas','Explore the workshop with artist Dadara on creativity in the age of AI.'],['Make a game together','Read about JSID’s Global Game Jam event.'],['Campus celebrations','See the North Eastern Day event in the news archive.']])}<div class="section-tight"><a class="text-link" href="https://js-instituteofdesign.com/news-events/" target="_blank" rel="noopener noreferrer">Browse the current event archive ↗</a></div></div></section>`}
function renderContact(params){const topic=params.get('topic')||'';const program=params.get('program')||'';return `${hero('Contact JSID','Talk to the right team','Ask a specific question, or contact Admissions directly.',{crumb:[['Contact',null]]})}<section class="section"><div class="container split-section" style="align-items:start"><div><h2>How can we help?</h2>${cards([['Admissions enquiries','Questions about programs, eligibility, costs and applications.'],['General enquiries','Questions about visiting, campus life or the institute.']])}<div class="section-tight"><h3>Contact Admissions</h3><p><a class="text-link" href="mailto:admissions@js-instituteofdesign.com">admissions@js-instituteofdesign.com ↗</a></p><p><a class="text-link" href="tel:+919667741699">+91 96677 41699 ↗</a></p><p>Confirm the campus address for your course and intake before visiting.</p></div></div><div><h3>Prepare an enquiry</h3><form id="contact-form"><div class="form-grid"><div class="form-field"><label for="contact-name">Name</label><input id="contact-name" name="name" autocomplete="name" required></div><div class="form-field"><label for="contact-email">Email</label><input id="contact-email" type="email" name="email" autocomplete="email" required></div><div class="form-field full"><label for="contact-topic">What is your question about?</label><select id="contact-topic" name="topic"><option value="general" ${!topic?'selected':''}>General enquiry</option><option value="cost" ${topic==='cost'?'selected':''}>Program costs</option><option value="admissions" ${topic==='admissions'?'selected':''}>Admissions</option><option value="alumni" ${topic==='alumni'?'selected':''}>Alumni</option><option value="high-school" ${topic==='high-school'?'selected':''}>High School Students</option><option value="faculty" ${topic==='faculty'?'selected':''}>Faculty / Careers</option></select></div><div class="form-field full"><label for="contact-program">Program (optional)</label><select id="contact-program" name="program"><option value="">No program selected</option>${programs.map(p=>`<option value="${p.slug}" ${program===p.slug?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</select></div><div class="form-field full"><label for="contact-message">Question</label><textarea id="contact-message" name="message" rows="5" required placeholder="Tell us what you need to know."></textarea></div></div><label class="checkbox"><input type="checkbox" required><span>I understand this enquiry will not be sent.</span></label><button class="button button-dark" type="submit">Review enquiry ↗</button><p class="form-note">No information is sent or saved here. Use the email or phone link to reach JSID.</p></form></div></div></section>`}
function renderCareers(){return `${hero('Careers at JSID','Join the team','Bring your practice and perspective into design education.',{crumb:[['Careers',null]]})}<section class="section"><div class="container">${cards([['Teach and mentor','Share expertise through teaching, critiques and workshops.'],['Work with the institute','Help shape student experience, admissions, operations or communication.']])}<div class="section-tight"><h2>Get in touch</h2><p>Contact JSID to ask about current openings and the right person to speak to.</p>${link('/contact?topic=faculty','Contact JSID ↗')}</div></div></section>`}
function renderLegal(type){const privacy=type==='privacy';const title=privacy?'Privacy Policy':'Terms & Conditions';const url=privacy?'https://js-instituteofdesign.com/privacy-policy/':'https://js-instituteofdesign.com/terms-condition/';return `${hero(title,'Information','Read JSID’s current published policy on its official website.',{crumb:[[title,null]]})}<section class="section"><div class="container" style="max-width:900px"><h2>${title}</h2><p>For the current official wording, use the published JS Institute of Design page below.</p><a class="button button-dark" href="${url}" target="_blank" rel="noopener noreferrer">Read ${title} ↗</a></div></section>`}
function renderSitemap(){const groups=[['Academics',[['Programs','/programs'],...programs.map(p=>[p.name,'/program/'+p.slug]),['Summer design experience','/high-school/summer'],['Winter design experience','/high-school/winter']]],['Admissions',[['Admissions','/admissions'],['Apply','/apply']]],['Explore JSID',[['Student Outcomes','/student-outcomes'],['Alumni','/alumni'],['Campus Life','/campus-life'],['Parents','/parents'],['About JSID','/about'],['Founding Team','/founding-team'],['Faculty','/faculty']]],['More',[['News & Media','/news-media'],['Blog','/blog'],['Contact','/contact'],['Careers','/careers'],['Privacy Policy','/privacy'],['Terms','/terms']]]];return `${hero('Sitemap','Find a route','Browse the site structure in one place.',{crumb:[['Sitemap',null]]})}<section class="section"><div class="container"><div class="card-grid">${groups.map(([name,links])=>`<div class="route-card"><h3>${name}</h3>${links.map(([label,url])=>`<a class="text-link" style="margin:.3rem 0" href="#${url}">${escapeHtml(label)} ↗</a>`).join('')}</div>`).join('')}</div></div></section>`}
function render404(){return `${hero('Page not found','404','The route may have moved. Choose a useful way back.',{crumb:[['Page not found',null]],actions:`${link('/','Go to homepage','button button-dark')}${link('/programs','Explore programs','button button-outline')}`})}`}
function footer(){const groups=[['Explore',[['Academics','/programs'],['Admissions','/admissions'],['Apply','/apply'],['Student Outcomes','/student-outcomes']]],['Community',[['Alumni','/alumni'],['Campus Life','/campus-life'],['Parents','/parents'],['Faculty','/faculty']]],['Institute',[['About','/about'],['Founding Team','/founding-team'],['News & Media','/news-media'],['Blog','/blog']]],['Useful links',[['Contact','/contact'],['Careers','/careers'],['Sitemap','/sitemap'],['Privacy Policy','/privacy'],['Terms','/terms']]]];return `<div class="footer-top"><div class="footer-brand"><a class="brand" href="#/"><span class="brand-mark">JS<span>·</span>ID</span><span class="brand-caption">Institute<br>of Design</span></a><p>Explore programs, people and life at JS Institute of Design.</p></div>${groups.map(([title,links])=>`<div class="footer-col"><strong>${title}</strong>${links.map(([label,url])=>`<a href="#${url}">${label}</a>`).join('')}</div>`).join('')}</div><div class="footer-bottom"><span>© JS Institute of Design · 2026</span><span>Programs · People · Campus Life</span></div>`}
function mobileNav(){return [['Academics','/programs'],...programs.map(p=>[p.name,'/program/'+p.slug,true]),['Summer offering','/high-school/summer',true],['Winter offering','/high-school/winter',true],['Admissions','/admissions'],['Student Outcomes','/student-outcomes'],['Alumni','/alumni'],['Campus Life','/campus-life'],['Parents','/parents'],['About','/about'],['Founding Team','/founding-team',true],['Faculty','/faculty',true],['News & Media','/news-media'],['Blog','/blog'],['Contact','/contact'],['Apply','/apply']].map(([label,url,sub])=>`<a class="${sub?'mobile-sub':''}" href="#${url}">${escapeHtml(label)}</a>`).join('')}
function navPanel(name){const data={academics:{title:'Explore Academics',desc:'Find a program by discipline or explore short high-school offerings.',links:[['All programs','/programs'],['Interior Design','/programs?discipline=Interior%20Design'],['Digital Design','/programs?discipline=Digital%20Design'],['Summer design experience','/high-school/summer'],['Winter design experience','/high-school/winter']]},about:{title:'About JSID',desc:'Learn about the institute and meet the people behind the work.',links:[['About JSID','/about'],['Founding Team','/founding-team'],['Faculty','/faculty'],['Careers','/careers']]},more:{title:'More from JSID',desc:'News, ideas and the right contact route.',links:[['News & Media','/news-media'],['Blog','/blog'],['Contact','/contact']]}}[name];return `<div class="nav-panel-inner"><div><span class="nav-panel-label">${data.title}</span><p>${data.desc}</p></div><div class="nav-panel-grid">${data.links.map(([label,url])=>`<a href="#${url}">${label} ↗</a>`).join('')}</div></div>`}
function currentRoute(){let hash=location.hash||'#/';if(hash.startsWith('#/')===false)return {path:'/',params:new URLSearchParams()};let raw=hash.slice(1).split('#')[0],idx=raw.indexOf('?');return {path:idx>=0?raw.slice(0,idx):raw,params:new URLSearchParams(idx>=0?raw.slice(idx+1):'')}}
function closeMenus(){const panel=$('#nav-panel');panel.hidden=true;document.querySelectorAll('.nav-trigger').forEach(b=>b.setAttribute('aria-expanded','false'));$('#mobile-nav').hidden=true;$('#mobile-menu-button').setAttribute('aria-expanded','false');document.body.style.overflow=''}
function render(){closeMenus();const {path,params}=currentRoute();if(path==='/apply'&&app.lastPath!=='/apply'){app.applyStep=1;app.application={}}let html;if(path==='/')html=renderHome();else if(path==='/programs'){if(params.has('discipline'))app.filter.discipline=params.get('discipline');html=renderPrograms()}else if(path==='/compare')html=renderCompare();else if(path.startsWith('/program/')){const p=programs.find(x=>x.slug===path.split('/')[2]);html=p?renderProgram(p):render404()}else if(path==='/admissions')html=renderAdmissions();else if(path==='/apply'){if(params.get('program'))app.application.program=params.get('program');html=renderApply()}else if(path==='/parents')html=renderParents();else if(path==='/student-outcomes')html=renderOutcomes();else if(path==='/alumni')html=renderAlumni();else if(path==='/faculty')html=renderFaculty();else if(path==='/about')html=renderAbout();else if(path==='/founding-team')html=renderFounders();else if(path==='/campus-life')html=renderCampus();else if(path==='/high-school/summer')html=renderSchool('Summer');else if(path==='/high-school/winter')html=renderSchool('Winter');else if(path==='/news-media')html=renderEditorial('news');else if(path==='/blog')html=renderEditorial('blog');else if(path==='/events')html=renderEvents();else if(path==='/contact')html=renderContact(params);else if(path==='/careers')html=renderCareers();else if(path==='/privacy')html=renderLegal('privacy');else if(path==='/terms')html=renderLegal('terms');else if(path==='/sitemap')html=renderSitemap();else html=render404();$('#main').innerHTML=html;$('#site-footer').innerHTML=footer();document.title=(pages.find(x=>x[1]===path)?.[0]||programs.find(x=>'/program/'+x.slug===path)?.name||'JSID')+' — JS Institute of Design';if(path==='/programs'){const d=$('#discipline-filter'),l=$('#level-filter');d.value=app.filter.discipline;l.value=app.filter.level;updatePrograms()}app.lastPath=path;updateCompareTray();const anchor=decodeURIComponent(location.hash.split('#').slice(2).join('#'));if(anchor){setTimeout(()=>document.getElementById(anchor)?.scrollIntoView(),50)}else window.scrollTo({top:0,behavior:'instant'});}
function updatePrograms(){let list=programs.filter(p=>(app.filter.discipline==='All disciplines'||p.discipline===app.filter.discipline)&&(app.filter.level==='All levels'||p.level===app.filter.level)&&(`${p.name} ${p.discipline} ${p.level}`.toLowerCase().includes(app.filter.query.toLowerCase())));$('#program-grid').innerHTML=list.length?list.map(programCard).join(''):`<div class="empty-state"><h3>No matching programs</h3><p>Try a broader search or clear a filter.</p></div>`;$('#program-count').textContent=`Showing ${list.length} of ${programs.length} programs`}
function updateCompareTray(){const el=$('#compare-tray'),route=currentRoute().path;if(!app.compare.length||!(route==='/programs'||route==='/compare'||route.startsWith('/program/'))){el.hidden=true;return}el.hidden=false;el.innerHTML=`<div class="compare-tray-inner"><div><strong>${app.compare.length} of 2 programs selected</strong><div style="font-size:.78rem;opacity:.8">${app.compare.map(s=>escapeHtml(programs.find(p=>p.slug===s)?.name||'')).join(' · ')}</div></div><div class="form-actions" style="margin:0"><button class="button button-small button-outline" style="color:var(--bg);border-color:var(--bg)" data-clear-compare>Clear</button><a class="button button-small button-yellow" href="#/compare" ${app.compare.length<2?'aria-disabled="true"':''}>Compare now ↗</a></div></div>`}
function showToast(message){const t=$('#toast');t.textContent=message;t.hidden=false;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.hidden=true,3500)}
function openModal(html){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="Dialog"><button type="button" class="modal-close" data-close-modal aria-label="Close dialog">×</button>${html}</div></div>`;$('#modal-root .modal').querySelector('input,select,button:not(.modal-close)')?.focus();document.body.style.overflow='hidden'}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow=''}
function openBrochure(slug){const p=programs.find(x=>x.slug===slug);openModal(`<span class="eyebrow">Program information</span><h2>Explore a brochure</h2><p>${p?`Looking for details about <strong>${escapeHtml(p.name)}</strong>? `:''}JSID publishes its current brochures on the official institute website.</p><a class="button button-dark" href="https://js-instituteofdesign.com/e-brochure/" target="_blank" rel="noopener noreferrer">Browse JSID brochures ↗</a>`)}
function openSearch(){openModal(`<span class="eyebrow">Site search</span><h2>What are you looking for?</h2><div class="form-field"><label for="site-search-input">Search pages and programs</label><input id="site-search-input" type="search" autocomplete="off" placeholder="Try admissions, faculty, game art…"></div><div id="site-search-results" class="search-results"></div>`);updateSearch('')}
function updateSearch(q){const hits=[...pages.map(([label,path])=>({label,path,type:'Page'})),...programs.map(p=>({label:p.name,path:'/program/'+p.slug,type:'Program'}))].filter(x=>x.label.toLowerCase().includes(q.toLowerCase())).slice(0,q?12:8);$('#site-search-results').innerHTML=hits.length?hits.map(x=>`<a href="#${x.path}" data-close-on-route><small>${x.type}</small>${escapeHtml(x.label)}</a>`).join(''):'<p>No results. Try a broader term.</p>'}
function setTheme(){if(app.theme==='auto'){document.documentElement.removeAttribute('data-theme')}else document.documentElement.dataset.theme=app.theme;$('#theme-button').title=app.theme==='auto'?'Theme: automatic':`Theme: ${app.theme}`;$('#theme-button').setAttribute('aria-label',`Theme: ${app.theme}. Switch theme`)}
document.addEventListener('click',e=>{const menu=e.target.closest('[data-menu]');if(menu){const name=menu.dataset.menu,panel=$('#nav-panel'),open=menu.getAttribute('aria-expanded')==='true';document.querySelectorAll('.nav-trigger').forEach(b=>b.setAttribute('aria-expanded','false'));panel.hidden=open;if(!open){panel.innerHTML=navPanel(name);menu.setAttribute('aria-expanded','true')}return}if(e.target.closest('#mobile-menu-button')){const nav=$('#mobile-nav'),open=!nav.hidden;nav.hidden=open;$('#mobile-menu-button').setAttribute('aria-expanded',String(!open));document.body.style.overflow=open?'':'hidden';return}if(e.target.closest('#search-button')){openSearch();return}if(e.target.closest('#theme-button')){app.theme=app.theme==='auto'?'dark':app.theme==='dark'?'light':'auto';localStorage.setItem('jsid-theme',app.theme);setTheme();showToast(`Theme: ${app.theme}`);return}const comp=e.target.closest('[data-compare]');if(comp){const slug=comp.dataset.compare,at=app.compare.indexOf(slug);if(at>=0)app.compare.splice(at,1);else if(app.compare.length<2)app.compare.push(slug);else{showToast('Choose two programs. Remove one before adding another.');return}document.querySelectorAll(`[data-compare="${slug}"]`).forEach(b=>{b.setAttribute('aria-pressed',app.compare.includes(slug));b.textContent=app.compare.includes(slug)?'Added':'Compare +'});updateCompareTray();return}if(e.target.closest('[data-clear-compare]')){app.compare=[];document.querySelectorAll('[data-compare]').forEach(b=>{b.setAttribute('aria-pressed','false');b.textContent='Compare +'});updateCompareTray();return}const brochure=e.target.closest('[data-brochure]');if(brochure){openBrochure(brochure.dataset.brochure);return}if(e.target.closest('[data-close-modal]')||e.target.classList.contains('modal-backdrop')){closeModal();return}if(e.target.closest('[data-apply-back]')){app.applyStep=Math.max(1,app.applyStep-1);render();return}if(e.target.closest('[data-apply-finish]')){app.applyStep=4;app.application={};render();return}if(e.target.closest('[data-anchor]')){e.preventDefault();document.getElementById(e.target.closest('[data-anchor]').dataset.anchor)?.scrollIntoView({behavior:'smooth'});return}if(e.target.closest('[data-audience]')){sessionStorage.setItem('jsid-audience',e.target.closest('[data-audience]').dataset.audience)}if(e.target.closest('[data-close-on-route]'))closeModal();if(e.target.closest('#compare-tray a[aria-disabled="true"]')){e.preventDefault();showToast('Select two programs to compare.')}});
document.addEventListener('input',e=>{if(e.target.id==='program-search'){app.filter.query=e.target.value;updatePrograms()}if(e.target.id==='site-search-input')updateSearch(e.target.value)});
document.addEventListener('change',e=>{if(e.target.id==='discipline-filter'){app.filter.discipline=e.target.value;updatePrograms()}if(e.target.id==='level-filter'){app.filter.level=e.target.value;updatePrograms()}});
document.addEventListener('submit',e=>{if(e.target.id==='contact-form'){e.preventDefault();e.target.innerHTML=`<span class="eyebrow">Review complete</span><h3>Enquiry reviewed.</h3><p>No message was sent.</p>`;return}if(e.target.id==='apply-program-form'){e.preventDefault();app.application.program=$('#apply-program').value;app.applyStep=2;render();return}if(e.target.id==='apply-details-form'){e.preventDefault();app.application.name=$('#applicant-name').value;app.application.email=$('#applicant-email').value;app.applyStep=3;render();return}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeMenus()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}});
window.addEventListener('hashchange',()=>{closeModal();render()});
$('#mobile-nav').innerHTML=mobileNav();setTheme();render();
